begin;
do $$
declare org uuid; member uuid; eid uuid; other uuid; template text:='test-onboarding-'||gen_random_uuid(); tid2 text:='test-onboarding-'||gen_random_uuid(); packet jsonb; view jsonb; token text; firstid uuid; secondid uuid; before_count integer; signedid uuid; service uuid; rateid uuid;
begin
 select organization_id,user_id into org,member from organization_members limit 1;perform set_config('request.jwt.claim.sub',member::text,true);
 eid:=nodara_save_entity_profile(jsonb_build_object('organization_id',org,'name','Onboarding Test','roles',jsonb_build_array('customer','shipper'),'email','owner@example.test'),jsonb_build_array(jsonb_build_object('name','Owner','email','owner@example.test','roles',jsonb_build_array('operations'),'is_primary',true)),jsonb_build_array(jsonb_build_object('line1','1 Main St','address_type','BILLING','is_primary',true)),jsonb_build_object('legal_name','Onboarding Test LLC','customer_type','Direct customer','payment_terms','Net 30'));
 assert (select roles @> array['customer','shipper'] from entities where id=eid),'Roles not saved';
 assert (select legal_name='Onboarding Test LLC' from entity_legal_profiles where entity_id=eid),'Legal profile not saved';
 insert into service_catalog(organization_id,code,name,domain,default_unit) values(org,'ONBOARD_'||gen_random_uuid(),'Onboarding recurring test','WAREHOUSE','EA') returning id into service;
 insert into customer_rate_agreements(organization_id,customer_id,service_id,sell_rate,currency,unit,effective_from,effective_to) values(org,eid,service,12,'USD','EA',current_date,current_date+365) returning id into rateid;
 assert exists(select 1 from entity_onboarding_requirements r join entity_onboarding_profiles p on p.id=r.onboarding_profile_id where p.entity_id=eid and r.requirement_code='SERVICE_AGREEMENT' and r.status='SATISFIED'),'Customer rate sheet did not satisfy commercial readiness';
 select count(*) into before_count from entities;
 begin perform nodara_save_entity_profile(jsonb_build_object('organization_id',org,'name','Invalid','roles',jsonb_build_array('customer')),'[]','[{"name":"Missing street"}]','{}');raise exception 'Invalid profile unexpectedly saved';exception when others then if sqlerrm='Invalid profile unexpectedly saved' then raise;end if;end;
 assert (select count(*)=before_count from entities),'Invalid address left partial entity';
 insert into document_templates(id,organization_id,name,status,placements,design) values(template,org,'Information','published','[{"module":"Customers","surface":"Onboarding"}]','{"pageW":215.9,"pageH":279.4,"objects":[{"type":"text","text":"Profile confirmation"}],"onboardingFields":[{"key":"customer.legal_name","label":"Legal company name","required":true},{"key":"contact.name","label":"Operations contact"},{"key":"contact.email","label":"Contact email"},{"key":"billing.address","label":"Billing street"}]}'),(tid2,org,'Agreement','published','[{"module":"Customers","surface":"Onboarding"}]','{"objects":[{"type":"text","text":"Agreement terms"}],"onboardingFields":[]}');
 packet:=nodara_create_onboarding_packet(eid,'Owner','owner@example.test',jsonb_build_array(jsonb_build_object('template_id',template,'document_type','CUSTOMER_INFORMATION'),jsonb_build_object('template_id',tid2,'document_type','RATE_AGREEMENT')));token:=packet->>'token';
 perform set_config('request.jwt.claim.sub','',true);
 execute 'set local role anon';
 view:=nodara_onboarding_packet(token);
 begin perform nodara_review_onboarding_document(gen_random_uuid(),true);raise exception 'Anonymous reviewer allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';
 firstid:=(view->'documents'->0->>'id')::uuid;secondid:=(view->'documents'->1->>'id')::uuid;
 begin perform nodara_onboarding_packet('invalid');raise exception 'Invalid token accepted';exception when others then if sqlerrm='Invalid token accepted' then raise;end if;end;
 begin perform nodara_onboarding_packet(token,jsonb_build_object('document_id',secondid,'signer_name','Owner','signer_email','owner@example.test','consent',true));raise exception 'Out of order signature accepted';exception when others then if sqlerrm='Out of order signature accepted' then raise;end if;end;
 begin perform nodara_onboarding_packet(token,jsonb_build_object('document_id',firstid,'signer_name','Owner','signer_email','wrong@example.test','consent',true));raise exception 'Wrong email accepted';exception when others then if sqlerrm='Wrong email accepted' then raise;end if;end;
 begin perform nodara_onboarding_packet(token,jsonb_build_object('document_id',firstid,'signer_name','Owner','signer_email','owner@example.test','consent',true,'responses','{}'));raise exception 'Missing field accepted';exception when others then if sqlerrm='Missing field accepted' then raise;end if;end;
 view:=nodara_onboarding_packet(token,jsonb_build_object('document_id',firstid,'signer_name','Owner','signer_email','owner@example.test','signer_title','Owner','consent',true,'responses',jsonb_build_object('customer.legal_name','Onboarding Test LLC','contact.name','Customer Operations','contact.email','customerops@example.test','billing.address','2 Updated St')));
 select document_id into signedid from entity_onboarding_packet_documents where id=firstid;
 assert signedid is not null,'Signed document not archived';
 assert (select content_hash=encode(extensions.digest(jsonb_build_object('template',template_snapshot,'prefill',prefill,'responses',responses,'signer',signer_name,'title',signer_title,'version',template_version,'document_type',document_type,'email',signer_email,'consent',consent_text,'time',submitted_at)::text,'sha256'),'hex') from entity_onboarding_packet_documents where id=firstid),'Signature hash does not match stored record';
 assert exists(select 1 from document_links where document_id=signedid and entity_id=eid),'Signed document not linked to entity';
 assert (select status='PENDING' from entity_onboarding_requirements where document_id=signedid),'Signature bypassed review';
 perform nodara_onboarding_packet(token,jsonb_build_object('document_id',firstid,'signer_name','Changed','signer_email','wrong@example.test','consent',false));
 assert (select signer_name='Owner' from entity_onboarding_packet_documents where id=firstid),'Retry modified signature';
 assert (select count(*)=1 from documents where metadata->>'onboarding_packet_document_id'=firstid::text),'Retry duplicated signed document';
 update document_templates set design='{"objects":[{"type":"text","text":"Changed terms"}]}' where id=tid2;
 perform set_config('request.jwt.claim.sub',member::text,true);
 update customer_rate_agreements set sell_rate=99 where id=rateid;
 perform set_config('request.jwt.claim.sub','',true);
 view:=nodara_onboarding_packet(token);assert (view->'documents'->1->'prefill'->'rate_sheet'->0->>'rate')::numeric=12,'Rate sheet snapshot changed after pricing edit';
 assert view->'documents'->1->'design'->'objects'->0->>'text'='Agreement terms','Template update changed signature snapshot';
 view:=nodara_onboarding_packet(token,jsonb_build_object('document_id',secondid,'signer_name','Owner','signer_email','owner@example.test','signer_title','Owner','consent',true));assert view->>'status'='COMPLETED','Packet not completed';
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform nodara_review_onboarding_document(firstid,true);raise exception 'Nonmember review allowed';exception when others then if sqlerrm='Nonmember review allowed' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',member::text,true);perform nodara_review_onboarding_document(firstid,true);
 assert (select status='SATISFIED' from entity_onboarding_requirements where document_id=signedid),'Review did not satisfy requirement';
 assert exists(select 1 from entity_contacts where entity_id=eid and is_primary and name='Customer Operations' and email='customerops@example.test'),'Reviewed form did not update operations contact';
 assert exists(select 1 from entity_addresses where entity_id=eid and address_type='BILLING' and line1='2 Updated St'),'Reviewed form did not update billing address';
 perform nodara_revoke_onboarding_packet((packet->>'id')::uuid);
 begin perform nodara_onboarding_packet(token);raise exception 'Revoked token accepted';exception when others then if sqlerrm='Revoked token accepted' then raise;end if;end;
 update entity_onboarding_packets set status='OPEN',expires_at=now()-interval '1 minute' where id=(packet->>'id')::uuid;
 begin perform nodara_onboarding_packet(token);raise exception 'Expired token accepted';exception when others then if sqlerrm='Expired token accepted' then raise;end if;end;
 assert not has_table_privilege('anon','entity_onboarding_packets','SELECT'),'Anonymous raw packet access';
 assert not has_schema_privilege('anon','nodara_private','USAGE'),'Anonymous token table access';
end $$;
rollback;
